// HasUpstreamConfig applies the HasEdge predicate on the "upstream_config" edge.
func HasUpstreamConfig() predicate.UpstreamAuthSession {
	return predicate.UpstreamAuthSession(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, UpstreamConfigTable, UpstreamConfigColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasUpstreamConfigWith applies the HasEdge predicate on the "upstream_config" edge with a given conditions (other predicates).
func HasUpstreamConfigWith(preds ...predicate.UpstreamConfig) predicate.UpstreamAuthSession {
	return predicate.UpstreamAuthSession(func(s *sql.Selector) {
		step := newUpstreamConfigStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UpstreamAuthSession) predicate.UpstreamAuthSession {
	return predicate.UpstreamAuthSession(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UpstreamAuthSession) predicate.UpstreamAuthSession {
	return predicate.UpstreamAuthSession(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UpstreamAuthSession) predicate.UpstreamAuthSession {
	return predicate.UpstreamAuthSession(sql.NotPredicates(p))
}
